// Patch notes: one entry per gameplay commit, newest first.
// Generated by scripts/generate-patches.mjs — do not hand-edit. Re-run to pick up new commits.
// Each patch is a commit: `hash` is the source of truth, `summary` is the player-facing note,
// and `n` is the stable patch number (Patch 1 is the oldest gameplay change).
export interface Patch {
  n: number; hash: string; short: string; date: string; title: string; summary: string; tags: string[];
}

export const PATCHES: Patch[] = [
  { n: 46, hash: "fb6bb03cc775f9481fd2caa0099040f336a5db20", short: "fb6bb03", date: "2026-09-13", title: "Put the monsters back on the player's power curve", summary: "The dungeon pushes back now — monsters ride the same power curve you do, so shiny gear stops auto-winning past depth 2, and loot runs scarcer. Every trip down matters. Deep runs, deep consequences.", tags: ["combat", "dungeon", "saves", "town"] },
  { n: 45, hash: "fb51f59dc6e4e9edfbb10960f9e6f22fcbf7c222", short: "fb51f59", date: "2026-09-12", title: "ashen king bestiary update", summary: "He is home: the ASHEN KING waits on depth 6. Bring everything.", tags: ["combat"] },
  { n: 44, hash: "48357f5dbc633b72fe6bab3c09fcf957a5c00ca8", short: "48357f5", date: "2026-09-12", title: "Make the codex obey Shift like everything else", summary: "The whole codex follows one rule from here on: plain words, numbers on Shift, swapped live without losing your place.", tags: ["art", "combat", "docs"] },
  { n: 43, hash: "fa0420d8d1f755df4e0137823e840179f05daa06", short: "fa0420d", date: "2026-09-12", title: "Say it in words, and in numbers when you hold Shift", summary: "Relics talk plain now — hold Shift (or tap on touch) when you want the raw numbers. The codex shows both at once.", tags: ["combat", "docs"] },
  { n: 42, hash: "2700d73d614e864ead4d688728334035594b59ba", short: "2700d73", date: "2026-09-12", title: "Unlock a relic when you hold it, name it when it is appraised", summary: "Finding a relic is not knowing it — it counts the moment you grab it, but the appraiser has to name it before the codex opens its page. Mystery lump stays mysterious.", tags: ["combat", "docs", "dungeon", "saves"] },
  { n: 41, hash: "ecc90cbfc658fa036821583216074fba9f746222", short: "ecc90cb", date: "2026-09-12", title: "Give the hollow knight the same shield and guard", summary: "The Hollow Knight guards now too. Same rules as the rest: respect the raise.", tags: ["art", "combat", "docs"] },
  { n: 40, hash: "3d8fb824e9a61b08e70164ec98fb6f79d52fa24e", short: "3d8fb82", date: "2026-09-12", title: "Give shields a readable guard rhythm plus a block pose", summary: "Shield enemies telegraph now: watch the raise — swing into it and you will eat a bash and a stun. Chip the hold three times and their guard sags open.", tags: ["art", "combat", "docs", "dungeon"] },
  { n: 39, hash: "12b96d9ae335ed9f03d50c45d32f271a56a9952b", short: "12b96d9", date: "2026-09-12", title: "Put real numbers in every relic rule, and stop saying \"wind\"", summary: "Every relic tells you exactly what it does, in real numbers. No more flowery guessing — and stamina is called stamina.", tags: ["combat", "docs", "dungeon"] },
  { n: 38, hash: "4ff430fd66a26b912a58ce49da6113c9126c05f1", short: "4ff430f", date: "2026-09-12", title: "Replace generated Legendaries with nine named relics", summary: "Nine named relics replace random legendaries — a sword that never dulls, a dagger that banks parries, a shield that throws hits back, a lamp that is a terrible shield, plate that eats half your healing, and one you DRINK. The Ashen King always drops one you have never held.", tags: ["combat", "docs", "dungeon", "saves"] },
  { n: 37, hash: "c988bbd361b4725e56dfce6dce98ad7545a5cc31", short: "c988bbd", date: "2026-09-12", title: "Add goblin archer and shieldbearers that punish spam", summary: "New faces that punish button-mashing: goblin archers open up from range, and shieldbearers shrug off 75% of everything from the front. Flank them, time them, or back off.", tags: ["art", "combat", "docs", "dungeon"] },
  { n: 36, hash: "2429c1712daf90a75e60d7d4022f0579ba9a8b72", short: "2429c17", date: "2026-09-12", title: "Fix floating creatures escaping the codex pane, add the Ember Wisp", summary: "Something warm and angry haunts depth 3: the Ember Wisp burns and hates the frost. Your first real elemental matchup.", tags: ["art", "combat", "docs"] },
  { n: 35, hash: "953e22c9c39b1b09c5b1acf5a4bfd141f0689963", short: "953e22c", date: "2026-09-12", title: "Gate the animation bench to dev, and track combat tallies per creature", summary: "The codex keeps your grudges: kills, deaths, your biggest hit landed and the worst you ever took, per creature.", tags: ["combat", "docs", "dungeon"] },
  { n: 34, hash: "75122c1edf90d235c3d1adaac51f435661bfa76c", short: "75122c1", date: "2026-09-12", title: "Add the bestiary codex and an animation bench", summary: "There is a bestiary now! Kills earn names, field notes drop off the creature they describe — read them where they fall — and full entries spill resistances. Know what is coming.", tags: ["art", "combat", "docs", "dungeon", "saves"] },
  { n: 33, hash: "92ddc6068017ba49728c83444ac9493916e32e36", short: "92ddc60", date: "2026-09-12", title: "Fill out the bestiary and turn the typecheck back on", summary: "New blood: cave bats swarm the shallows (bring something slashy), and a rotting champion with a maul holds depths 5–6 (bring a mace, trust us).", tags: ["art", "combat", "docs", "town"] },
  { n: 32, hash: "293d4837a75739430556cd7b9f879e647dc13d49", short: "293d483", date: "2026-09-12", title: "Make the dagger a crit weapon worth building around", summary: "Daggers are the crit weapon now: they crit for 2.4x and their crit chance grows with the metal. Stack luck and watch things melt.", tags: ["combat", "docs"] },
  { n: 31, hash: "3f298b18325f80a7bbb25faa2ee7c05da23b3994", short: "3f298b1", date: "2026-09-12", title: "Make physical damage a triangle and give the pick its point back", summary: "Damage finally has a triangle: blunt crushes bone, slash opens flesh, pierce punches through plate. Bring the right tool — the pick is pierce again, and faster.", tags: ["combat", "docs"] },
  { n: 30, hash: "0a27ba4a5b6808353bb31f9756d918168e37a2d9", short: "0a27ba4", date: "2026-09-12", title: "Separate the weapon classes and stop free swings on an empty bar", summary: "Weapons have real personalities: quick blades, heavy hafts that sip stamina, and a long spear that outranges everything. And no more free swings on an empty bar — every swing is paid for.", tags: ["audio", "combat", "docs", "dungeon", "town"] },
  { n: 29, hash: "52ec1ea41e36bc0a336b6f7733ec6d187c3eb9a1", short: "52ec1ea", date: "2026-09-12", title: "Give town study its own sound instead of the arcade sweep", summary: "Studying blueprints and appraising finds got their own papery, leathery sound. Knowledge has ambience now.", tags: ["audio"] },
  { n: 28, hash: "b1a1b52b1d33b0ce2e5304cc6046bd0972088970", short: "b1a1b52", date: "2026-09-12", title: "Order gear into power lines and make strong blueprints rare", summary: "Gear runs in power lines now — every base beats the last one forged two metals better — and the strong blueprints are properly rare. Chase the ladder.", tags: ["docs", "town"] },
  { n: 27, hash: "7e05c19d6065f418fd9a12f3bf8d59d5690e5607", short: "7e05c19", date: "2026-09-12", title: "Make Rock and Stone a mining pick secret", summary: "Rumor: the mining pick hides a secret. Rock and Stone, miner.", tags: ["art", "docs", "dungeon"] },
  { n: 26, hash: "3e885db849c44c529dcef0b2db5cd88df69762f1", short: "3e885db", date: "2026-09-12", title: "Stack blueprints and redraw mining pick", summary: "Blueprints stack now instead of clogging your stash, and the mining pick got a fresh look.", tags: ["art", "saves"] },
  { n: 25, hash: "195bbf904245a7c4221b96ea1058fef080b73654", short: "195bbf9", date: "2026-09-12", title: "Polish blueprint list interactions", summary: "The blueprint shelf got tidier: clearer progress, easier upgrades, no more squinting.", tags: ["core"] },
  { n: 24, hash: "772acc03bda6bc6c5dd90b1c5c9a998491ec64b6", short: "772acc0", date: "2026-09-12", title: "Polish forge progression and mobile saves", summary: "Endgame materials hit way harder — star iron, dragon scale, moonsilver, the lot — and a new Sunstone gem feeds holy builds. Forging high-tier finally pays.", tags: ["docs", "saves", "town"] },
  { n: 23, hash: "bf6ef58c851ce8f8cc7828193cac1fd4e5f04101", short: "bf6ef58", date: "2026-09-12", title: "Rebalance loot and make blueprints master recipes", summary: "Loot got rebalanced and blueprints are master recipes now: spare copies feed mastery all the way to Rank 5 instead of gathering dust.", tags: ["docs", "dungeon", "saves", "town"] },
  { n: 22, hash: "68556c243f5d4541293dbd557e51ec7955d19a4e", short: "68556c2", date: "2026-09-12", title: "Three save slots, and stop the debounce from settling conflicts", summary: "Three save slots — three whole playthroughs, each living on your device and in the cloud. Pick your poison on the title screen.", tags: ["saves"] },
  { n: 21, hash: "b1a022e231434108c80a435ec15745c58114db2c", short: "b1a022e", date: "2026-09-12", title: "Sync saves in the background, and ask when two disagree", summary: "Your saves drift to the cloud in the background, and when two devices disagree, YOU pick the winner — never mid-delve, never silently.", tags: ["saves"] },
  { n: 20, hash: "69da1cafc19fad208aa47a4fc0e4a4ebbab06aa9", short: "69da1ca", date: "2026-09-12", title: "Sign in by emailed code, and the shape of a cloud save", summary: "Accounts are here, and totally optional: get a code by email, sign in, and carry your delves from laptop to phone. Offline players lose nothing.", tags: ["saves"] },
  { n: 19, hash: "3df228d2f3a3110f2096913eebc8b3b2754adc3f", short: "3df228d", date: "2026-09-12", title: "Sprung traps leave wreckage, and it stays", summary: "Dead traps stay on the floor as wreckage — bent plates, collapsed spikes, shattered wards. You will remember where you have been.", tags: ["art", "docs", "dungeon"] },
  { n: 18, hash: "d325893713aeae706386483424f881d81ba1afd8", short: "d325893", date: "2026-09-12", title: "Add the mining pick", summary: "New weapon: the mining pick. Quick for its punch with a taste for crits — and the forge knows its recipe.", tags: ["art", "dungeon", "town"] },
  { n: 17, hash: "5871a6356366f0955ab15f92a279f38cf7320a3c", short: "5871a63", date: "2026-09-12", title: "Add durability: gear wears where it is used, the forge mends it", summary: "Your gear wears down fighting: weapons dull on every landed blow, shields soak what you block, armour suffers what gets through. Broken gear still fights at quarter strength, and the forge mends the lot — broken first — with one Mend All button.", tags: ["docs", "dungeon", "town"] },
  { n: 16, hash: "7b3bfeacb9f7092fcc24fda58a9465570d4c22de", short: "7b3bfea", date: "2026-09-12", title: "Shrines in three flavours, and curses to answer them", summary: "Three shrines now, readable from across the room: blue font heals you clean and lifts curses, violet idol gambles blessings against curses that follow you all run, gold stone sells blessings for coin up front. Feeling lucky?", tags: ["art", "docs", "dungeon", "saves"] },
  { n: 15, hash: "32ff6d1e55a466004e36b25f9f7fb37999f0f825", short: "32ff6d1", date: "2026-09-12", title: "Give the mimic legs and real teeth", summary: "Mimics unfold spindly legs when they spring and hit like vault guardians. That hoard is guarded for a reason.", tags: ["art", "combat", "docs", "dungeon"] },
  { n: 14, hash: "d29dc2ba57b8cbeb7643ceed49f9b87795dd9952", short: "d29dc2b", date: "2026-09-12", title: "Add mimic chests with a quiet tell", summary: "Some chests are lying to you. Learn the tell before you reach.", tags: ["art", "combat", "docs", "dungeon", "saves"] },
  { n: 13, hash: "81f5572a34b0b0b039a214d87d28ffa1cda485a8", short: "81f5572", date: "2026-09-12", title: "Keep shallow turn-backs on the same day", summary: "Popping back up from depth 1 does not turn the day anymore — the market and the guild only move when you have actually been somewhere.", tags: ["dungeon", "saves"] },
  { n: 12, hash: "d46a8eebe7ec822f7fa6a0abd68dbb0a0d109de6", short: "d46a8ee", date: "2026-09-12", title: "Make traps readable, stop loot stealing the tap, close the renown loop", summary: "Traps glint cold iron now so your eyes stand a chance, loot stops hijacking your taps mid-brawl, and chickening out at depth 1 pays exactly nothing. No more free renown.", tags: ["art", "docs", "dungeon"] },
  { n: 11, hash: "667f68cb073f3b5952b2b81c2c6d20b93aae18cc", short: "667f68c", date: "2026-09-12", title: "Add Lantern Wick: buy a little more light", summary: "Hate the dark? The Warden sells lamplight now: three ranks of Lantern Wick stretch your torch further, and the first rank spots traps a tile sooner.", tags: ["docs", "dungeon"] },
  { n: 10, hash: "0dc7f001819db3f780cf8b804bb6e5cf6d543dbf", short: "0dc7f00", date: "2026-09-12", title: "Add parries: deny the hit, stagger melee, reflect bolts", summary: "Parrying is in! Snap your guard up at the last instant and the hit fizzles — zero damage, zero stamina — while melee attackers reel for a full second of double damage. Even arrows: smack them back into whoever shot them.", tags: ["audio", "combat", "docs", "dungeon", "saves"] },
  { n: 9, hash: "ca998450a2477291d6988bd4ca365aacc2523d5e", short: "ca99845", date: "2026-09-12", title: "Rework the first-person hand, fix the knight's floating sword", summary: "Your hand looks like a hand now — fingers, bracer, the works — and the Hollow Knight finally holds his sword instead of wearing it through the chest. The title screen lists the real controls too.", tags: ["art", "combat", "dungeon"] },
  { n: 8, hash: "0dacefdcfe1255944e0a41104464065e6585e460", short: "0dacefd", date: "2026-09-12", title: "Town portals, packing from the stash, and free the boss hoard", summary: "Recall scrolls do not end your run anymore — they rip open a two-way portal home. Bank your gold, restock, then step back to the exact depth you left. Pack your bag from the stash before you descend, and the boss hoard finally drops where you can grab it.", tags: ["art", "docs", "dungeon", "saves"] },
  { n: 7, hash: "741429975e57f1d900f9eab30faa0c7b654c78ac", short: "7414299", date: "2026-09-12", title: "Add traps: dart plates, spike pits and alarm wards", summary: "The floor fights back: dart plates, spike pits, and alarm wards that scream every monster in earshot toward you. Walk slow, watch the ground, pry up what you spot for free salvage — and lure chasers onto the spikes you already found.", tags: ["art", "docs", "dungeon", "saves"] },
  { n: 6, hash: "8daf2004a07ed131d380ed2dcf851d511c62a6b4", short: "8daf200", date: "2026-09-11", title: "In-app updates for the installed app; silence audio in background", summary: "The installed app updates itself and never nags you mid-run. Tab away and your run pauses with the sound off — come back and it is all still there.", tags: ["audio"] },
  { n: 5, hash: "be7fac0bb094e50cf45c40676d385739dfaaf4fb", short: "be7fac0", date: "2026-09-11", title: "Drag-to-move touch controls, smart action button, A/D turn", summary: "Ditch the D-pad: drag anywhere to walk and turn, with one smart button that swings when there is something to hit and grabs when there is something to take.", tags: ["docs", "dungeon", "mobile"] },
  { n: 4, hash: "35dbdbdc95314142fc28d4b31d23c85130eb555c", short: "35dbdbd", date: "2026-09-11", title: "Always-available fullscreen toggle with landscape lock", summary: "One fullscreen button, pinned on every screen, with landscape lock. You will never hunt for it again.", tags: ["mobile"] },
  { n: 3, hash: "4218a746df7a3cf91ef685ffee4422755b8f1f45", short: "4218a74", date: "2026-09-11", title: "Compact phone UI, fullscreen everywhere, installable web app", summary: "The game fits in your pocket now: compact phone layout, fullscreen everywhere, installable to your home screen. Panels finally behave on small screens.", tags: ["dungeon", "mobile"] },
  { n: 2, hash: "63a3a3424e9bee33619f46f57784b1387dabeb1e", short: "63a3a34", date: "2026-09-11", title: "Touch controls, no health regen, harder monsters", summary: "Phone players, you are in: full touch controls. And nobody heals by standing around anymore — bring supplies or do not bleed. Oh, and monsters hit harder.", tags: ["combat", "dungeon", "mobile", "saves"] },
  { n: 1, hash: "7147fc8c66166737c4101c79bb1af60d6280a1db", short: "7147fc8", date: "2026-09-11", title: "Overhaul: PS1 renderer, real-time combat, loot economy, pixel art", summary: "Everything is new. First-person dungeon crawling with real-time combat — read the wind-up, dodge or block — torchlight and fog, six floors, a boss at the bottom, and a full loot loop of market, forge and contracts. All in crunchy PS1 pixel art.", tags: ["art", "audio", "combat", "docs", "dungeon", "saves", "town"] },
];

